//! Ammann–Beenker A5 (octagonal) aperiodic tiling by substitution.
//!
//! Prototiles: a unit square — split along a diagonal into two labelled
//! half-square triangles — and a unit 45° rhombus. The inflation factor is
//! the silver mean `λ = 1+√2`; every vertex of every child lies in the
//! module generated by the 8 unit directions, i.e. all coordinates are
//! `m + n·√2` with rational `m, n`.
//!
//! Substitution counts (forced by exact area algebra; PF matrix
//! `[[3,2],[4,3]]`, Perron eigenvalue `λ² = 3+2√2`):
//!
//! ```text
//! rhombus -> 3 rhombi + 2 squares
//! square  -> 3 squares + 4 rhombi
//! ```
//!
//! The half-square labels are the heart of the rule: `RSquare` and
//! `LSquare` have the SAME geometric shape (a 45-45-90 triangle) but
//! different substitution rules. Every interior square diagonal is shared
//! by one R half and one L half, and it is exactly this labelling that
//! makes the rule consistent across parent boundaries (verified to depth 4
//! in exact arithmetic — see the verification note at the bottom).
//!
//! Canonical pieces (45° corner at the origin, first edge along +x;
//! orientation `k` rotates by `45°·k` CCW):
//!
//! * rhombus: `(0,0), (1,0), (1+√2/2, √2/2), (√2/2, √2/2)`
//! * half-square, both labels: `(0,0), (1,0), (1,1)` — hypotenuse from the
//!   first to the third corner, right angle at the second.
//!
//! Child tables below are transcribed verbatim from the canonical published
//! recipe (8-direction integer coordinates; children of the rhombus / R
//! half / L half). Each child anchor is given in the λ-inflated parent
//! frame as `(m + n·√2)/2` per component plus an orientation delta.
//! Dividing by `λ = 1+√2` — exact on such coordinates: `(m, n) ->
//! (2n−m, m−n)` — yields the *deflation* children that tile the unit
//! parent, which is the form used here.
//!
//! Boundary partitions the tables realize (and that make growth
//! edge-to-edge): an inflated rhombus leg splits `{1, √2}` with the unit
//! piece at the acute corner; an inflated half-square leg splits
//! `{1, √2}` with the unit piece at the 45° corner and its hypotenuse
//! splits `{1, √2, 1}` with the `√2` piece centred.
//!
//! Verification history (exact `Q(√2)` arithmetic, Python, before this
//! implementation): each rule's children tile its inflated parent exactly
//! (area, sampled coverage, sub-edge parity); the rhombus rule is
//! 180°-symmetric; growing the 8-rhombus star stays edge-to-edge with
//! R/L hypotenuse pairing and the PF count matrix through depth 4.
//! The Rust tests re-check the per-parent covers, the count matrix,
//! edge-to-edge growth and the 8-fold symmetry of the star patches.
//!
//! Generation mirrors the Penrose module: seed with the 8-rhombus star
//! scaled to cover the view (its inscribed radius is `√2/2·scale`), then
//! repeatedly deflate — each step replaces a piece by its children at 1/λ,
//! which tile the parent exactly, so per-step culling to the region never
//! drops a needed tile — until the pieces reach unit scale. Finally the
//! halves are paired back into squares across shared hypotenuses (lone
//! boundary halves are emitted as triangles).

use std::collections::BTreeMap;

use tess_core::geometry::{BBox, Polygon, Vec2};
use tess_core::params::{ParamSet, ParamSpec};
use tess_core::symmetry::{LatticeKind, SymmetryMeta, WallpaperGroup};
use tess_core::TilingCategory;
use tess_core::tiling::{Query, Tile, Tiling, TilingResult};
use tess_core::view::ColorMode;

use crate::lattice::{similarity_map, MAX_TILES, SCALE_ID, SIMILARITY_PARAMS};

const SQRT_2: f64 = std::f64::consts::SQRT_2;
/// Silver mean inflation factor 1+√2.
const LAM: f64 = 1.0 + SQRT_2;
/// √2/2 — cos 45° = sin 45°.
const S2: f64 = SQRT_2 / 2.0;
/// Refinement cap: λ^20 ≈ 4.5e7 units of seed reach. Beyond ~20 inflation
/// levels the accumulated float error would approach the 1e-7 pairing-key
/// grid, so such extreme zoom-outs fail with a message instead.
const STEP_CAP: usize = 20;

/// Prototile kinds: the rhombus and the two same-shaped half-square labels.
const RHOMB: u8 = 0;
const RSQ: u8 = 1;
const LSQ: u8 = 2;

static RHOMB_SHAPE: [Vec2; 4] = [
    Vec2::new(0.0, 0.0),
    Vec2::new(1.0, 0.0),
    Vec2::new(1.0 + S2, S2),
    Vec2::new(S2, S2),
];
// Both half-square labels share this shape; R/L are rule labels only.
static HALF_SHAPE: [Vec2; 3] = [
    Vec2::new(0.0, 0.0),
    Vec2::new(1.0, 0.0),
    Vec2::new(1.0, 1.0),
];

fn shape(kind: u8) -> &'static [Vec2] {
    if kind == RHOMB {
        &RHOMB_SHAPE
    } else {
        &HALF_SHAPE
    }
}

/// One substitution child: `(prototile kind, orientation delta, m, n)`
/// where the child anchor in the λ-inflated parent frame is
/// `((m[0] + n[0]·√2)/2, (m[1] + n[1]·√2)/2)` — i.e. `m` holds the two
/// rational parts (x, y) and `n` the two √2 parts.
type Child = (u8, i32, [i32; 2], [i32; 2]);

/// Rhombus → 3 rhombi + 2 squares (one R and one L half each).
const RHOMB_RULE: [Child; 7] = [
    (RHOMB, 0, [0, 0], [0, 0]),
    (RHOMB, 0, [2, 2], [2, 0]), // (1+√2, 1)
    (RHOMB, 6, [2, 2], [1, 1]), // (1+√2/2, 1+√2/2)
    (RSQ, 3, [2, 0], [2, 0]),   // (1+√2, 0)
    (RSQ, 7, [2, 2], [1, 1]),   // (1+√2/2, 1+√2/2)
    (LSQ, 0, [0, 0], [1, 1]),   // (√2/2, √2/2)
    (LSQ, 4, [4, 2], [2, 0]),   // (2+√2, 1)
];

/// RSquare half → 2 rhombi + 3 halves.
const RSQ_RULE: [Child; 5] = [
    (RHOMB, 0, [0, 0], [0, 0]),
    (RHOMB, 2, [2, 0], [2, 0]), // (1+√2, 0)
    (LSQ, 0, [0, 0], [1, 1]),   // (√2/2, √2/2)
    (RSQ, 3, [2, 0], [2, 0]),   // (1+√2, 0)
    (RSQ, 5, [2, 2], [2, 2]),   // (1+√2, 1+√2)
];

/// LSquare half → 2 rhombi + 3 halves.
const LSQ_RULE: [Child; 5] = [
    (RHOMB, 7, [0, 0], [1, 1]), // (√2/2, √2/2)
    (RHOMB, 1, [2, 0], [1, 1]), // (1+√2/2, √2/2)
    (LSQ, 3, [0, 0], [2, 0]),   // (√2, 0)
    (RSQ, 0, [0, 0], [1, 1]),   // (√2/2, √2/2)
    (LSQ, 5, [2, 0], [2, 2]),   // (1+√2, √2)
];

fn rule(kind: u8) -> &'static [Child] {
    match kind {
        RSQ => &RSQ_RULE,
        LSQ => &LSQ_RULE,
        _ => &RHOMB_RULE,
    }
}

/// A piece: prototile `kind`, orientation (`k` 45° CCW steps from the
/// canonical frame), anchor position of the 45° corner, and edge scale
/// (unit pieces have `s == 1`).
#[derive(Clone, Copy, Debug)]
struct Piece {
    kind: u8,
    k: i32,
    p: Vec2,
    s: f64,
}

fn rot45(v: Vec2) -> Vec2 {
    Vec2::new(S2 * (v.x - v.y), S2 * (v.x + v.y))
}

/// Rotate by `k` 45° CCW steps.
fn rot(v: Vec2, k: i32) -> Vec2 {
    let mut v = v;
    for _ in 0..k.rem_euclid(8) {
        v = rot45(v);
    }
    v
}

impl Piece {
    fn verts(&self) -> Vec<Vec2> {
        shape(self.kind)
            .iter()
            .map(|&c| self.p + rot(c, self.k) * self.s)
            .collect()
    }

    fn poly(&self) -> Polygon {
        Polygon::from_slice(&self.verts())
    }

    fn aabb(&self) -> BBox {
        let mut lo = Vec2::new(f64::MAX, f64::MAX);
        let mut hi = Vec2::new(f64::MIN, f64::MIN);
        for &c in shape(self.kind) {
            let q = self.p + rot(c, self.k) * self.s;
            lo.x = lo.x.min(q.x);
            lo.y = lo.y.min(q.y);
            hi.x = hi.x.max(q.x);
            hi.y = hi.y.max(q.y);
        }
        BBox::new(lo, hi)
    }

    /// Substitution children at 1/λ of this piece's scale; they exactly
    /// tile this piece (deflation view).
    fn children(&self) -> Vec<Piece> {
        let s2 = self.s / LAM;
        rule(self.kind)
            .iter()
            .map(|&(kind, dk, m, n)| {
                // The child anchor lives in the λ-inflated parent frame as
                // (m + n·√2)/2. Dividing the frame down to the parent
                // itself divides by λ = 1+√2, which maps (m, n) to
                // (2n−m, m−n) — exact in Z[√2].
                let mo = [2 * n[0] - m[0], 2 * n[1] - m[1]];
                let no = [m[0] - n[0], m[1] - n[1]];
                let off = Vec2::new(
                    0.5 * (mo[0] as f64 + no[0] as f64 * SQRT_2),
                    0.5 * (mo[1] as f64 + no[1] as f64 * SQRT_2),
                );
                Piece {
                    kind,
                    k: self.k + dk,
                    p: self.p + rot(off, self.k) * self.s,
                    s: s2,
                }
            })
            .collect()
    }
}

/// The "star" seed: 8 rhombi meeting at the origin — the classic AB seed
/// with perfect 8-fold symmetry. Its outer boundary is a 16-gon of
/// inradius `√2/2·scale`.
fn seed_star(scale: f64) -> Vec<Piece> {
    (0..8)
        .map(|k| Piece {
            kind: RHOMB,
            k,
            p: Vec2::ZERO,
            s: scale,
        })
        .collect()
}

/// One deflation step: replace every piece by its substitution children
/// (scale 1/λ), which tile the parent exactly.
///
/// Culling is sound: a child never leaves its parent, so a final piece
/// intersecting `region` has an ancestor chain whose aabbs all intersect
/// `region` — nothing needed is ever dropped.
fn refine_step(pieces: &[Piece], region: &BBox) -> Vec<Piece> {
    let mut out = Vec::with_capacity(pieces.len() * 5);
    for t in pieces {
        for ch in t.children() {
            if ch.aabb().intersects(*region) {
                out.push(ch);
            }
        }
    }
    out
}

/// Key of the unordered segment `(a, b)` on the 1e-7 grid (the same
/// convention as the Penrose half-tile pairing; Z[√2] lattice points
/// reached through different substitution paths agree to far below half a
/// grid step at the scales STEP_CAP allows).
fn seg_key(a: Vec2, b: Vec2) -> (i64, i64, i64, i64) {
    let (ax, ay) = ((a.x * 1e7).round() as i64, (a.y * 1e7).round() as i64);
    let (bx, by) = ((b.x * 1e7).round() as i64, (b.y * 1e7).round() as i64);
    if (ax, ay) <= (bx, by) {
        (ax, ay, bx, by)
    } else {
        (bx, by, ax, ay)
    }
}

/// Ammann–Beenker A5 tiling (aperiodic, squares + 45° rhombi, local
/// 8-fold symmetry).
pub struct AmmannBeenkerTiling;

impl Tiling for AmmannBeenkerTiling {
    fn id(&self) -> &'static str {
        "ammann-beenker"
    }

    fn name(&self) -> &'static str {
        "Ammann-Beenker (A5)"
    }

    fn description(&self) -> &'static str {
        "Quasiperiodic square-rhombus tiling by substitution; local 8-fold symmetry."
    }

    fn category(&self) -> TilingCategory {
        TilingCategory::Quasiperiodic
    }

    fn params(&self) -> &'static [ParamSpec] {
        &SIMILARITY_PARAMS
    }

    fn default_color_mode(&self) -> ColorMode {
        ColorMode::Pattern
    }

    fn generate(&self, params: &ParamSet, query: &Query) -> TilingResult {
        let meta = SymmetryMeta::new(WallpaperGroup::P1, LatticeKind::None)
            .with_notes("aperiodic; local 8-fold symmetry");
        let fail = |message: &'static str| TilingResult {
            tiles: Vec::new(),
            symmetry: meta,
            periodic: None,
            message: Some(message),
        };

        let map = similarity_map(params);
        let inv = map.inverse();

        // Region in the tiling's own (cell) coordinates: the axis-aligned
        // box around the inverse image of the four world corners.
        let mut rmin = Vec2::new(f64::MAX, f64::MAX);
        let mut rmax = Vec2::new(f64::MIN, f64::MIN);
        for &corner in &query.region.corners() {
            let q = inv.transform(corner);
            rmin.x = rmin.x.min(q.x);
            rmin.y = rmin.y.min(q.y);
            rmax.x = rmax.x.max(q.x);
            rmax.y = rmax.y.max(q.y);
        }
        let region = BBox::new(rmin, rmax);

        // Farthest region corner from the origin (the seed star is
        // centered there).
        let mut reach: f64 = 0.0;
        for &corner in &region.corners() {
            reach = reach.max(corner.length());
        }
        if reach < 1e-9 {
            return fail("empty view");
        }

        // Pre-generation budget (mirrors lattice.rs): the returned tiles
        // must cover the query region and no AB tile exceeds the unit
        // square's area (cell units; tiles only get smaller than unit
        // scale), so this is a lower bound on the tile count — checked
        // before any refinement work.
        let s = params.float(SCALE_ID, 1.0);
        if query.region.area() / (s * s) > MAX_TILES as f64 {
            return fail("too many tiles for this view — zoom in");
        }

        // Seed scale: the star's inscribed radius is √2/2·scale, so pick
        // scale = λ^n with n minimal subject to √2·reach ≤ scale; the
        // refinement below then lands exactly on unit pieces.
        let mut scale = 1.0_f64;
        let mut steps = 0_usize;
        while SQRT_2 * reach > scale && steps < STEP_CAP {
            scale *= LAM;
            steps += 1;
        }
        if SQRT_2 * reach > scale * (1.0 + 1e-9) {
            return fail("view too far from the seed — pan back or zoom in");
        }

        let mut pieces = seed_star(scale);
        for _ in 0..steps {
            pieces = refine_step(&pieces, &region);
        }
        if pieces.is_empty() {
            return fail("empty view");
        }

        // Pair half-squares back into squares across their shared
        // hypotenuses (every interior hypotenuse carries one R and one L
        // half; hypotenuses on the patch boundary stay single).
        let mut groups: BTreeMap<(i64, i64, i64, i64), Vec<usize>> = BTreeMap::new();
        for (i, t) in pieces.iter().enumerate() {
            if t.kind == RHOMB {
                continue;
            }
            let b = t.p + rot(Vec2::new(1.0, 1.0), t.k) * t.s;
            groups.entry(seg_key(t.p, b)).or_default().push(i);
        }

        let mut tiles = Vec::new();
        for t in &pieces {
            if t.kind != RHOMB {
                continue;
            }
            let world = t.poly().transform(&map);
            if world.aabb().intersects(query.region) {
                tiles.push(Tile {
                    proto: 1,
                    seed: 1, level: steps as u8,
                    poly: world,
                });
            }
        }
        for (_, idxs) in groups {
            let poly = match idxs.as_slice() {
                [i, j] => {
                    let a = pieces[*i].verts();
                    let b = pieces[*j].verts();
                    Polygon::from_slice(&[a[0], a[1], a[2], b[1]])
                }
                [i] => pieces[*i].poly(),
                _ => return fail("internal error: hypotenuse shared by >2 halves"),
            };
            let world = poly.transform(&map);
            if world.aabb().intersects(query.region) {
                tiles.push(Tile {
                    proto: 0,
                    seed: 0, level: steps as u8,
                    poly: world,
                });
            }
        }

        if tiles.len() > MAX_TILES {
            return fail("too many tiles for this view — zoom in");
        }

        TilingResult {
            tiles,
            symmetry: meta,
            periodic: None,
            message: None,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn canonical_parent(kind: u8) -> Piece {
        Piece {
            kind,
            k: 0,
            p: Vec2::ZERO,
            s: LAM,
        }
    }

    /// Deterministic xorshift64 rng (same style as the lib tests).
    struct Rng(u64);
    impl Rng {
        fn f64(&mut self) -> f64 {
            let mut v = self.0;
            v ^= v << 13;
            v ^= v >> 7;
            v ^= v << 17;
            self.0 = v;
            (v >> 11) as f64 * (1.0 / 9007199254740992.0)
        }
    }

    /// Point in convex polygon (boundary counts as inside).
    fn poly_contains(vs: &[Vec2], q: Vec2) -> bool {
        let n = vs.len();
        let mut pos = false;
        let mut neg = false;
        for i in 0..n {
            let c = (vs[(i + 1) % n] - vs[i]).cross(q - vs[i]);
            if c > 1e-9 {
                pos = true;
            } else if c < -1e-9 {
                neg = true;
            }
        }
        !(pos && neg)
    }

    /// The children of `t` must exactly tile `t` itself (deflation view):
    /// every sampled point inside t lies in exactly one child, and the
    /// child areas sum to the parent's area.
    fn check_substitution(t: &Piece, label: &str) {
        let kids = t.children();
        let pa = t.poly().area();
        let kids_area: f64 = kids.iter().map(|k| k.poly().area()).sum();
        assert!(
            (kids_area - pa).abs() <= 1e-9 * pa,
            "{label}: child areas {kids_area} != parent {pa}"
        );

        let bb = t.aabb();
        let mut rng = Rng(0x517C_C1B7_2722_0A95);
        let mut checked = 0;
        for _ in 0..4000 {
            let q = Vec2::new(
                bb.min.x + rng.f64() * bb.size().x,
                bb.min.y + rng.f64() * bb.size().y,
            );
            if !poly_contains(&t.verts(), q) {
                continue;
            }
            let n = kids
                .iter()
                .filter(|k| poly_contains(&k.verts(), q))
                .count();
            assert!(n == 1, "{label}: point {q} covered by {n} children");
            checked += 1;
        }
        assert!(checked > 1500, "{label}: too few samples landed");
    }

    #[test]
    fn rhombus_substitution_tiles_parent() {
        check_substitution(&canonical_parent(RHOMB), "rhombus -> 3 rhombi + 2 squares");
    }

    #[test]
    fn rsquare_substitution_tiles_parent() {
        check_substitution(&canonical_parent(RSQ), "RSquare -> 2 rhombi + 3 halves");
    }

    #[test]
    fn lsquare_substitution_tiles_parent() {
        check_substitution(&canonical_parent(LSQ), "LSquare -> 2 rhombi + 3 halves");
    }

    // ---------- global consistency: refine the star ----------

    /// Substitute every piece once (no culling).
    fn refine_all(pieces: &[Piece]) -> Vec<Piece> {
        let mut out = Vec::with_capacity(pieces.len() * 5);
        for t in pieces {
            out.extend(t.children());
        }
        out
    }

    #[test]
    fn star_growth_counts_follow_substitution_matrix() {
        // rhombus -> 3r + 2R + 2L ; RSquare -> 2r + 2R + 1L ; LSquare ->
        // 2r + 1R + 2L. From the 8-rhombus star this gives the PF-orbit
        // (24, 16, 16), (136, 96, 96), (792, 560, 560).
        let mut pieces = seed_star(1.0);
        let (mut er, mut eq, mut el) = (8usize, 0usize, 0usize);
        for depth in 0..3u32 {
            pieces = refine_all(&pieces);
            let (r, q, l) = (
                3 * er + 2 * eq + 2 * el,
                2 * er + 2 * eq + el,
                2 * er + eq + 2 * el,
            );
            er = r;
            eq = q;
            el = l;
            let gr = pieces.iter().filter(|t| t.kind == RHOMB).count();
            let gq = pieces.iter().filter(|t| t.kind == RSQ).count();
            let gl = pieces.iter().filter(|t| t.kind == LSQ).count();
            assert_eq!(
                (gr, gq, gl),
                (er, eq, el),
                "depth {depth}: got ({gr}, {gq}, {gl}), want ({er}, {eq}, {el})"
            );
        }
    }

    /// Does point `q` lie strictly in the interior of segment `a-b`?
    fn on_edge_interior(q: Vec2, a: Vec2, b: Vec2) -> bool {
        let ab = b - a;
        let aq = q - a;
        if aq.cross(ab).abs() > 1e-9 {
            return false;
        }
        let s = aq.dot(ab);
        let l2 = ab.dot(ab);
        s > 1e-9 && s < l2 - 1e-9
    }

    #[test]
    fn star_growth_is_edge_to_edge() {
        // The deflation preserves area exactly (substitution matrix PF
        // eigenvalue λ²), and the whole-tile view — halves paired across
        // shared hypotenuses plus the rhombi — must be edge-to-edge.
        // Halves whose hypotenuse lies on the patch boundary stay single
        // (their partner lives outside the finite star) and are skipped
        // here, exactly like the Penrose test skips unpaired triangles.
        let star_area = 8.0 * S2;
        let mut pieces = seed_star(1.0);
        for depth in 0..2u32 {
            pieces = refine_all(&pieces);

            let area: f64 = pieces.iter().map(|t| t.poly().area()).sum();
            assert!(
                (area - star_area).abs() <= 1e-9 * star_area,
                "depth {depth}: piece area sum {area} != star area {star_area}"
            );

            let mut groups: BTreeMap<(i64, i64, i64, i64), Vec<usize>> = BTreeMap::new();
            for (i, t) in pieces.iter().enumerate() {
                if t.kind == RHOMB {
                    continue;
                }
                let b = t.p + rot(Vec2::new(1.0, 1.0), t.k) * t.s;
                groups.entry(seg_key(t.p, b)).or_default().push(i);
            }

            let mut wholes: Vec<Vec<Vec2>> = Vec::new();
            for t in pieces.iter().filter(|t| t.kind == RHOMB) {
                wholes.push(t.verts());
            }
            for idxs in groups.values() {
                assert!(
                    idxs.len() <= 2,
                    "depth {depth}: hypotenuse shared by {} halves",
                    idxs.len()
                );
                if idxs.len() == 2 {
                    let (a, b) = (pieces[idxs[0]], pieces[idxs[1]]);
                    assert_ne!(
                        a.kind, b.kind,
                        "depth {depth}: hypotenuse pairs same-label halves"
                    );
                    let (va, vb) = (a.verts(), b.verts());
                    wholes.push(vec![va[0], va[1], va[2], vb[1]]);
                }
            }

            for (i, r) in wholes.iter().enumerate() {
                for &v in r {
                    for (j, s) in wholes.iter().enumerate() {
                        if i == j {
                            continue;
                        }
                        let n = s.len();
                        for k in 0..n {
                            if on_edge_interior(v, s[k], s[(k + 1) % n]) {
                                panic!(
                                    "depth {depth}: T-junction — tile {i} vertex {v} \
                                     lies inside an edge of tile {j}"
                                );
                            }
                        }
                    }
                }
            }
        }
    }

    #[test]
    fn star_growth_is_8fold_symmetric() {
        // The labelled piece multiset must be invariant under a 45°
        // rotation about the origin: (kind, k, p) -> (kind, k+1, rot45 p).
        let mut pieces = seed_star(1.0);
        for _ in 0..2 {
            pieces = refine_all(&pieces);
        }
        type Key = (u8, i32, i64, i64);
        let key = |t: &Piece, r: bool| -> Key {
            let p = if r { rot45(t.p) } else { t.p };
            (
                t.kind,
                if r { t.k + 1 } else { t.k }.rem_euclid(8),
                (p.x * 1e4).round() as i64,
                (p.y * 1e4).round() as i64,
            )
        };
        let mut count: BTreeMap<Key, i32> = BTreeMap::new();
        for t in &pieces {
            *count.entry(key(t, false)).or_insert(0) += 1;
        }
        for t in &pieces {
            *count.entry(key(t, true)).or_insert(0) -= 1;
        }
        for (k, &n) in &count {
            assert_eq!(n, 0, "8-fold symmetry mismatch at {k:?}");
        }
    }
}